<?php require APPROOT.'/views/inc/header.php'; ?><div class="app-content"><div class="container py-4"><h1 class="h3">Bienes y constancias</h1><p class="text-secondary">Acuses de recibo con clave. No constituyen firma digital legal.</p><?php if(!empty($_SESSION['flash_error'])):?><div class="alert alert-danger"><?= htmlspecialchars($_SESSION['flash_error']);unset($_SESSION['flash_error']);?></div><?php endif;?><div class="row g-4"><section class="col-lg-6"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">EPP y ropa</h2><?php foreach($ppe as $p):?><div class="border-bottom py-3"><strong><?= htmlspecialchars($p->item_name) ?></strong><small class="d-block text-secondary"><?= htmlspecialchars($p->delivered_on) ?> · Talle <?= htmlspecialchars($p->size_label??'—') ?> · <?= htmlspecialchars($p->status) ?></small><?php if($p->status==='issued'):?><form class="d-flex gap-2 mt-2" method="post" action="<?= URLROOT ?>/employee/acknowledgePpe/<?= (int)$p->id ?>"><?= csrf_field() ?><input class="form-control form-control-sm" type="password" name="password" placeholder="Tu clave" required><button class="btn btn-sm btn-primary">Acusar recibo</button></form><?php endif;?></div><?php endforeach;?></div></div><div class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h5">Activos a mi cargo</h2><?php foreach($assets as $a):?><div class="border-bottom py-2"><strong><?= htmlspecialchars($a->asset_tag) ?></strong> · <?= htmlspecialchars($a->category_name) ?><small class="d-block text-secondary"><?= htmlspecialchars(trim(($a->brand??'').' '.($a->model??''))) ?></small></div><?php endforeach;?><?php if(!$assets):?><p class="text-secondary mb-0">Sin activos vigentes.</p><?php endif;?></div></div></section><section class="col-lg-6"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Notificaciones disciplinarias</h2><?php foreach($incidents as $i):?><article class="border-bottom py-3"><strong><?= htmlspecialchars($i->title?:employee_incident_type_label($i->incident_type)) ?></strong><p class="small mt-2"><?= nl2br(htmlspecialchars($i->description)) ?></p><span class="badge text-bg-secondary"><?= htmlspecialchars($i->workflow_status) ?></span><?php if($i->workflow_status==='notified'):?><form method="post" action="<?= URLROOT ?>/employee/acknowledgeIncident/<?= (int)$i->id ?>" class="mt-2"><?= csrf_field() ?><textarea class="form-control form-control-sm mb-2" name="statement" placeholder="Descargo u observación (opcional)"></textarea><input class="form-control form-control-sm mb-2" type="password" name="password" placeholder="Tu clave" required><div class="d-flex gap-2"><button class="btn btn-sm btn-primary" name="decision" value="received">Acusar recibo</button><button class="btn btn-sm btn-outline-danger" name="decision" value="refused">Dejar constancia de negativa</button></div></form><?php endif;?></article><?php endforeach;?><?php if(!$incidents):?><p class="text-secondary mb-0">Sin notificaciones.</p><?php endif;?></div></div></section></div></div></div><?php require APPROOT.'/views/inc/footer.php'; ?>
